import { memo, useMemo } from 'react'

import { scaleLinear } from '@visx/scale'
import { bin, extent } from 'd3-array'

import Box from '@mui/material/Box'
import Slider from '@mui/material/Slider'
import { useTheme } from '@mui/material/styles'

import { useHistogramSliderMetrics } from './HistogramSlider.metrics'

/** viewBox의 x축 user unit 폭. domain([0, 100])과 1:1로 맞춘다. */
const VIEWBOX_WIDTH = 100

export type HistogramSliderProps = {
  className?: string
  samples: number[]
  value: number
  onChange: (value: number) => void
}

function HistogramSlider(props: HistogramSliderProps) {
  const { className, samples, value, onChange } = props

  const { palette } = useTheme()
  const { histogramHeight, sliderHeight } = useHistogramSliderMetrics()

  const buckets = useMemo(() => bin().domain([0, 100])(samples), [samples])

  // 폭은 viewBox + preserveAspectRatio="none"로 CSS가 늘려주므로 측정하지 않는다.
  // (JS로 폭을 재면 첫 페인트 후 리사이즈되며 CLS가 발생한다.)
  const xScale = useMemo(() => {
    return scaleLinear({
      domain: [0, 100],
      range: [0, VIEWBOX_WIDTH],
    })
  }, [])

  const yScale = useMemo(() => {
    const domain = extent(buckets, ({ length }) => length) as [number, number]
    return scaleLinear({
      domain,
      range: [histogramHeight, 0],
      nice: true,
    })
  }, [histogramHeight, buckets])

  return (
    <div className={className}>
      <svg
        width="100%"
        height={histogramHeight}
        viewBox={`0 0 ${VIEWBOX_WIDTH} ${histogramHeight}`}
        preserveAspectRatio="none"
        // inline 기본값이면 line box descender 여백이 붙어 높이가 어긋난다.
        style={{ display: 'block' }}
      >
        {buckets.map(({ length, x0 = 0, x1 = 0 }, i) => {
          const x = xScale(x0)
          const y = yScale(length)
          return (
            <rect
              key={i}
              x={x}
              y={y}
              width={xScale(x1) - x}
              height={histogramHeight - y}
              fill={x0 < value ? palette.success.main : palette.grey[800]}
            />
          )
        })}
      </svg>
      <Box
        sx={{
          position: 'relative',
          height: sliderHeight,
          display: 'flex',
          alignItems: 'center',
        }}
      >
        <Slider
          sx={{
            width: 'calc(100% - .4rem)',
          }}
          step={100 / buckets.length}
          marks
          min={0}
          max={100}
          valueLabelDisplay="auto"
          value={value}
          onChange={(_, v) => typeof v === 'number' && onChange(v)}
        />
      </Box>
    </div>
  )
}

export default memo(HistogramSlider)
